@font-face {
  font-family: "Parastoo FD";
  src: url("./Parastoo-FD.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Parastoo FD";
  src: url("./Parastoo-Bold-FD.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
